#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

typedef struct {
    int x1, y1, x2, y2;
} Rectangle;

static int compare_ints(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

static int lower_bound_int(const int *a, int n, int value) {
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < value) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

/* Soma 1 ao retângulo inclusivo [x1..x2] x [y1..y2]
   em uma matriz de diferenças. */
static void add_rectangle(int *diff, int stride,
                          int x1, int y1, int x2, int y2) {
    diff[x1 * stride + y1] += 1;
    diff[(x2 + 1) * stride + y1] -= 1;
    diff[x1 * stride + (y2 + 1)] -= 1;
    diff[(x2 + 1) * stride + (y2 + 1)] += 1;
}

static void prefix_sum_2d(int *diff, int rows, int cols, int stride) {
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            int idx = i * stride + j;
            if (i > 0) diff[idx] += diff[idx - stride];
            if (j > 0) diff[idx] += diff[idx - 1];
            if (i > 0 && j > 0) diff[idx] -= diff[idx - stride - 1];
        }
    }
}

static void bit_set(unsigned char *bits, int index) {
    bits[index >> 3] |= (unsigned char)(1u << (index & 7));
}

static int bit_get(const unsigned char *bits, int index) {
    return (bits[index >> 3] >> (index & 7)) & 1;
}

/* Heap indexada: pos[v] é a posição de v na heap,
   -1 indica que não está na heap e -2 que já foi removido. */
static void heap_sift_up(int *heap, int *pos, const int *dist, int i) {
    while (i > 0) {
        int parent = (i - 1) / 2;
        if (dist[heap[parent]] <= dist[heap[i]]) break;

        int a = heap[parent], b = heap[i];
        heap[parent] = b;
        heap[i] = a;
        pos[a] = i;
        pos[b] = parent;
        i = parent;
    }
}

static void heap_sift_down(int *heap, int *pos, const int *dist,
                           int size, int i) {
    while (1) {
        int left = 2 * i + 1;
        int right = left + 1;
        int smallest = i;

        if (left < size && dist[heap[left]] < dist[heap[smallest]])
            smallest = left;
        if (right < size && dist[heap[right]] < dist[heap[smallest]])
            smallest = right;
        if (smallest == i) break;

        int a = heap[i], b = heap[smallest];
        heap[i] = b;
        heap[smallest] = a;
        pos[a] = smallest;
        pos[b] = i;
        i = smallest;
    }
}

static void heap_decrease_or_insert(int *heap, int *pos, const int *dist,
                                    int *size, int vertex) {
    if (pos[vertex] == -1) {
        int i = (*size)++;
        heap[i] = vertex;
        pos[vertex] = i;
        heap_sift_up(heap, pos, dist, i);
    } else {
        heap_sift_up(heap, pos, dist, pos[vertex]);
    }
}

static int heap_pop(int *heap, int *pos, const int *dist, int *size) {
    int result = heap[0];
    pos[result] = -2;
    --(*size);

    if (*size > 0) {
        heap[0] = heap[*size];
        pos[heap[0]] = 0;
        heap_sift_down(heap, pos, dist, *size, 0);
    }

    return result;
}

int main(void) {
    int xi, yi, xf, yf;
    if (scanf("%d %d %d %d", &xi, &yi, &xf, &yf) != 4) return 0;

    int n;
    if (scanf("%d", &n) != 1) return 0;

    Rectangle *rects = malloc((size_t)(n > 0 ? n : 1) * sizeof(Rectangle));
    int coord_capacity = 2 * n + 2;
    int *xs = malloc((size_t)coord_capacity * sizeof(int));
    int *ys = malloc((size_t)coord_capacity * sizeof(int));

    if (rects == NULL || xs == NULL || ys == NULL) {
        free(rects);
        free(xs);
        free(ys);
        return 0;
    }

    int nx_raw = 0, ny_raw = 0;
    xs[nx_raw++] = xi;
    xs[nx_raw++] = xf;
    ys[ny_raw++] = yi;
    ys[ny_raw++] = yf;

    for (int i = 0; i < n; ++i) {
        scanf("%d %d %d %d", &rects[i].x1, &rects[i].y1,
              &rects[i].x2, &rects[i].y2);
        xs[nx_raw++] = rects[i].x1;
        xs[nx_raw++] = rects[i].x2;
        ys[ny_raw++] = rects[i].y1;
        ys[ny_raw++] = rects[i].y2;
    }

    qsort(xs, (size_t)nx_raw, sizeof(int), compare_ints);
    qsort(ys, (size_t)ny_raw, sizeof(int), compare_ints);

    int nx = 0, ny = 0;
    for (int i = 0; i < nx_raw; ++i)
        if (nx == 0 || xs[i] != xs[nx - 1]) xs[nx++] = xs[i];
    for (int i = 0; i < ny_raw; ++i)
        if (ny == 0 || ys[i] != ys[ny - 1]) ys[ny++] = ys[i];

    int start_x = lower_bound_int(xs, nx, xi);
    int start_y = lower_bound_int(ys, ny, yi);
    int finish_x = lower_bound_int(xs, nx, xf);
    int finish_y = lower_bound_int(ys, ny, yf);

    /* Segmentos horizontais: índices (x-intervalo, y-ponto). */
    int h_rows = nx - 1;
    int h_cols = ny;
    int h_stride = h_cols + 1;
    size_t diff_size = (size_t)(h_rows + 1) * (size_t)h_stride;
    int *diff = calloc(diff_size, sizeof(int));
    if (diff == NULL) {
        free(rects);
        free(xs);
        free(ys);
        return 0;
    }

    for (int r = 0; r < n; ++r) {
        int a = lower_bound_int(xs, nx, rects[r].x1);
        int b = lower_bound_int(xs, nx, rects[r].x2);
        int c = lower_bound_int(ys, ny, rects[r].y1);
        int d = lower_bound_int(ys, ny, rects[r].y2);

        if (a < b)
            add_rectangle(diff, h_stride, a, c, b - 1, d);
    }

    prefix_sum_2d(diff, h_rows, h_cols, h_stride);

    size_t h_edges = (size_t)h_rows * (size_t)h_cols;
    size_t h_bytes = (h_edges + 7) / 8;
    unsigned char *horizontal_covered = calloc(h_bytes ? h_bytes : 1, 1);
    if (horizontal_covered == NULL) {
        free(diff);
        free(rects);
        free(xs);
        free(ys);
        return 0;
    }

    for (int i = 0; i < h_rows; ++i) {
        for (int j = 0; j < h_cols; ++j) {
            if (diff[i * h_stride + j] > 0)
                bit_set(horizontal_covered, j * h_rows + i);
        }
    }
    free(diff);

    /* Segmentos verticais: índices (x-ponto, y-intervalo). */
    int v_rows = nx;
    int v_cols = ny - 1;
    int v_stride = v_cols + 1;
    diff_size = (size_t)(v_rows + 1) * (size_t)v_stride;
    diff = calloc(diff_size, sizeof(int));
    if (diff == NULL) {
        free(horizontal_covered);
        free(rects);
        free(xs);
        free(ys);
        return 0;
    }

    for (int r = 0; r < n; ++r) {
        int a = lower_bound_int(xs, nx, rects[r].x1);
        int b = lower_bound_int(xs, nx, rects[r].x2);
        int c = lower_bound_int(ys, ny, rects[r].y1);
        int d = lower_bound_int(ys, ny, rects[r].y2);

        if (c < d)
            add_rectangle(diff, v_stride, a, c, b, d - 1);
    }

    prefix_sum_2d(diff, v_rows, v_cols, v_stride);

    size_t v_edges = (size_t)v_rows * (size_t)v_cols;
    size_t v_bytes = (v_edges + 7) / 8;
    unsigned char *vertical_covered = calloc(v_bytes ? v_bytes : 1, 1);
    if (vertical_covered == NULL) {
        free(diff);
        free(horizontal_covered);
        free(rects);
        free(xs);
        free(ys);
        return 0;
    }

    for (int i = 0; i < v_rows; ++i) {
        for (int j = 0; j < v_cols; ++j) {
            if (diff[i * v_stride + j] > 0)
                bit_set(vertical_covered, j * v_rows + i);
        }
    }

    free(diff);
    free(rects);

    int vertex_count = nx * ny;
    int *dist = malloc((size_t)vertex_count * sizeof(int));
    int *heap = malloc((size_t)vertex_count * sizeof(int));
    int *pos = malloc((size_t)vertex_count * sizeof(int));

    if (dist == NULL || heap == NULL || pos == NULL) {
        free(dist);
        free(heap);
        free(pos);
        free(vertical_covered);
        free(horizontal_covered);
        free(xs);
        free(ys);
        return 0;
    }

    for (int i = 0; i < vertex_count; ++i) {
        dist[i] = INT_MAX;
        pos[i] = -1;
    }

    int start = start_y * nx + start_x;
    int target = finish_y * nx + finish_x;
    int heap_size = 0;

    dist[start] = 0;
    heap_decrease_or_insert(heap, pos, dist, &heap_size, start);

    while (heap_size > 0) {
        int u = heap_pop(heap, pos, dist, &heap_size);
        if (u == target) break;

        int x = u % nx;
        int y = u / nx;

        /* Vizinho à direita. */
        if (x + 1 < nx) {
            int v = u + 1;
            int edge_idx = y * (nx - 1) + x;
            int cost = bit_get(horizontal_covered, edge_idx)
                       ? 0 : xs[x + 1] - xs[x];
            if (dist[u] + cost < dist[v]) {
                dist[v] = dist[u] + cost;
                heap_decrease_or_insert(heap, pos, dist, &heap_size, v);
            }
        }

        /* Vizinho à esquerda. */
        if (x > 0) {
            int v = u - 1;
            int edge_idx = y * (nx - 1) + (x - 1);
            int cost = bit_get(horizontal_covered, edge_idx)
                       ? 0 : xs[x] - xs[x - 1];
            if (dist[u] + cost < dist[v]) {
                dist[v] = dist[u] + cost;
                heap_decrease_or_insert(heap, pos, dist, &heap_size, v);
            }
        }

        /* Vizinho com coordenada y maior. */
        if (y + 1 < ny) {
            int v = u + nx;
            int edge_idx = y * nx + x;
            int cost = bit_get(vertical_covered, edge_idx)
                       ? 0 : ys[y + 1] - ys[y];
            if (dist[u] + cost < dist[v]) {
                dist[v] = dist[u] + cost;
                heap_decrease_or_insert(heap, pos, dist, &heap_size, v);
            }
        }

        /* Vizinho com coordenada y menor. */
        if (y > 0) {
            int v = u - nx;
            int edge_idx = (y - 1) * nx + x;
            int cost = bit_get(vertical_covered, edge_idx)
                       ? 0 : ys[y] - ys[y - 1];
            if (dist[u] + cost < dist[v]) {
                dist[v] = dist[u] + cost;
                heap_decrease_or_insert(heap, pos, dist, &heap_size, v);
            }
        }
    }

