        free(dist);
        free(heap);
        free(pos);
        free(vertical_covered);
        free(horizontal_covered);
        free(xs);
        free(ys);
        return 0;
    }

    for (int i = 0; i < vertex_count; ++i) {
        dist[i] = INT_MAX;
        pos[i] = -1;
    }

    int start = start_y * nx + start_x;
    int target = finish_y * nx + finish_x;
    int heap_size = 0;

    dist[start] = 0;
    heap_decrease_or_insert(heap, pos, dist, &heap_size, start);

    while (heap_size > 0) {
        int u = heap_pop(heap, pos, dist, &heap_size);
        if (u == target) break;

        int x = u % nx;
        int y = u / nx;

        /* Vizinho à direita. */
        if (x + 1 < nx) {
            int v = u + 1;
            int edge_idx = y * (nx - 1) + x;
            int cost = bit_get(horizontal_covered, edge_idx)
                       ? 0 : xs[x + 1] - xs[x];
            if (dist[u] + cost < dist[v]) {
                dist[v] = dist[u] + cost;
                heap_decrease_or_insert(heap, pos, dist, &heap_size, v);
            }
        }

        /* Vizinho à esquerda. */
        if (x > 0) {
            int v = u - 1;
            int edge_idx = y * (nx - 1) + (x - 1);
            int cost = bit_get(horizontal_covered, edge_idx)
                       ? 0 : xs[x] - xs[x - 1];
            if (dist[u] + cost < dist[v]) {
                dist[v] = dist[u] + cost;
                heap_decrease_or_insert(heap, pos, dist, &heap_size, v);
            }
        }

        /* Vizinho com coordenada y maior. */
        if (y + 1 < ny) {
            int v = u + nx;
            int edge_idx = y * nx + x;
            int cost = bit_get(vertical_covered, edge_idx)
                       ? 0 : ys[y + 1] - ys[y];
            if (dist[u] + cost < dist[v]) {
                dist[v] = dist[u] + cost;
                heap_decrease_or_insert(heap, pos, dist, &heap_size, v);
            }
        }

        /* Vizinho com coordenada y menor. */
        if (y > 0) {
            int v = u - nx;
            int edge_idx = (y - 1) * nx + x;
            int cost = bit_get(vertical_covered, edge_idx)
                       ? 0 : ys[y] - ys[y - 1];
            if (dist[u] + cost < dist[v]) {
                dist[v] = dist[u] + cost;
                heap_decrease_or_insert(heap, pos, dist, &heap_size, v);
            }
        }
    }

    printf("%d\n", dist[target]);

    free(dist);
    free(heap);
    free(pos);
    free(vertical_covered);
    free(horizontal_covered);
    free(xs);
    free(ys);
    return 0;
}
